function renderCollection(){let grid=document.getElementById('collectionGrid'),list=[...cards],sort=document.getElementById('sortCards').value;list.sort((a,b)=>sort==='name'?a.name.localeCompare(b.name):sort==='power'?b.power-a.power:b.stars-a.stars);grid.innerHTML=list.map(c=>{let found=!!state.owned[c.id];return `<div class="collection-entry">${cardMarkup(c)}${found?'':`<div class="locked-label">✧ UNKNOWN ✧</div>`}</div>`}).join('');let count=Object.keys(state.owned).length;document.getElementById('collectionCount').textContent=`${count} / 8 DISCOVERED`;document.getElementById('collectionHint').textContent=count===8?'A complete constellation — beautifully done.':`${8-count} companions remain beyond the veil.`;grid.querySelectorAll('.collection-entry').forEach(el=>{let id=el.querySelector('.card3d').dataset.id;if(!state.owned[id])el.querySelector('.card3d').classList.add('locked');else el.onclick=()=>{selectedCard=id;nav('workshop')}});tiltCards(grid)}
document.getElementById('sortCards').onchange=renderCollection;
function renderWorkshop(){let owned=cards.filter(c=>state.owned[c.id]);let list=document.getElementById('workshopList');if(!owned.length){list.innerHTML='<div class="upgrade-empty" style="padding:35px">✧<b>No companions yet</b><span>Summon a card to begin your workshop.</span></div>';document.getElementById('upgradePanel').innerHTML='<div class="upgrade-empty">✧<b>Your starforge is quiet</b><span>Discover a companion to awaken their power.</span></div>';return}list.innerHTML=owned.map(c=>`<div class="workshop-item ${selectedCard===c.id?'selected':''}" data-id="${c.id}" style="--accent:${c.accent};--hair:${c.hair};--outfit:${c.outfit}"><div class="mini-art"></div><div><b>${c.name}</b><small>${c.rarity} · ${c.element}</small></div><span class="lvl">Lv.${state.levels[c.id]||1}</span></div>`).join('');list.querySelectorAll('.workshop-item').forEach(el=>el.onclick=()=>{selectedCard=el.dataset.id;renderWorkshop()});if(!selectedCard||!state.owned[selectedCard])selectedCard=owned[0].id;let c=cards.find(x=>x.id===selectedCard),level=state.levels[c.id]||1,cost=25+level*20,power=Math.round(c.power*(1+(level-1)*.12)),next=Math.round(c.power*(1+level*.12)),pct=Math.min(100,power/1100*100),panel=document.getElementById('upgradePanel');panel.innerHTML=`<div class="upgrade-content">${cardMarkup(c)}<div class="upgrade-info"><div class="eyebrow">STARFORGE · ${c.element}</div><h2>${c.name}</h2><div class="sub">${c.title} · Level ${level}${level>=10?' · MAX':''}</div><div class="power-line"><span>COMBAT POWER</span><b>${power} <span style="color:#9e87bc">→ ${level>=10?'MAX':next}</span></b></div><div class="power-track"><i style="width:${pct}%"></i></div><p class="quote">“${c.quote}”</p><div class="upgrade-cost">✦ Upgrade cost: ${level>=10?'MAX LEVEL':cost+' shards'} &nbsp;·&nbsp; Have ${state.shards}</div><button id="upgradeBtn" class="btn btn-primary upgrade-btn" ${state.shards<cost||level>=10?'disabled':''}>${level>=10?'MAX LEVEL':'✧ Awaken companion'}</button></div></div>`;document.getElementById('upgradeBtn').onclick=()=>{if(state.shards<cost||level>=10)return;state.shards-=cost;state.levels[c.id]=level+1;save();showToast(`${c.name} awakened to level ${level+1}!`);renderWorkshop()};tiltCards(panel)}
document.getElementById('dailyBtn').onclick=()=>{if(Date.now()-state.lastDaily<86400000){let hours=Math.ceil((86400000-(Date.now()-state.lastDaily))/3600000);showToast(`Your next gift arrives in ${hours}h.`);return}state.gems+=300;state.shards+=40;state.lastDaily=Date.now();save();showToast('Daily gift claimed: 300 gems + 40 shards!')};
document.getElementById('rateInfo').onclick=()=>showToast('Rates: Legendary 2.5% · Epic 12.5% · Rare 33% · Common 52% · Epic+ guaranteed within 10 pulls.');
document.getElementById('bannerArt').innerHTML=[cards[2],cards[0],cards[1]].map(c=>cardMarkup(c)).join('');tiltCards(document.getElementById('bannerArt'));updateHud();renderCollection();
</script>

